{"cmd":"cat <<'EOF' > /root/output/js/visualization.js
/* global d3 */
(() => {
  const tooltip = d3.select('#tooltip');
  const state = {
    selected: null,
    priceCache: new Map(),
  };

  const palette = [
    ...d3.schemeTableau10,
    ...d3.schemeSet3,
    ...d3.schemePaired,
    ...d3.schemeSet2,
  ];

  const formatMarketCap = (value) => {
    if (!value || Number.isNaN(value)) return '—';
    const abs = Math.abs(value);
    const fmt = (num, suffix) => {
      const fixed = num.toFixed(2).replace(/\.00$/, '').replace(/(\.\d)0$/, '$1');
      return `${fixed}${suffix}`;
    };
    if (abs >= 1e12) return fmt(value / 1e12, 'T');
    if (abs >= 1e9) return fmt(value / 1e9, 'B');
    if (abs >= 1e6) return fmt(value / 1e6, 'M');
    if (abs >= 1e3) return fmt(value / 1e3, 'K');
    return String(value);
  };

  const loadPriceHistory = (ticker) => {
    if (state.priceCache.has(ticker)) {
      return Promise.resolve(state.priceCache.get(ticker));
    }
    return d3.csv(`data/indiv-stock/${ticker}.csv`).then((rows) => {
      const parsed = rows
        .map((row) => ({
          date: new Date(row.Date),
          close: Number(row.Close) || Number(row['Adjusted Close']),
        }))
        .filter((d) => d.date instanceof Date && !Number.isNaN(d.close));
      state.priceCache.set(ticker, parsed);
      return parsed;
    });
  };

  const renderSparkline = (container, series) => {
    container.selectAll('*').remove();
    if (!series || series.length === 0) {
      container.append('div').text('Price history unavailable');
      return;
    }
    const slice = series.slice(Math.max(0, series.length - 90));
    const width = 170;
    const height = 52;
    const padding = 6;
    const x = d3.scaleLinear()
      .domain([0, slice.length - 1])
      .range([padding, width - padding]);
    const y = d3.scaleLinear()
      .domain(d3.extent(slice, (d) => d.close))
      .range([height - padding, padding]);

    const line = d3.line()
      .x((d, i) => x(i))
      .y((d) => y(d.close))
      .curve(d3.curveMonotoneX);

    const svg = container.append('svg')
      .attr('width', width)
      .attr('height', height);

    svg.append('path')
      .datum(slice)
      .attr('d', line)
      .attr('fill', 'none')
      .attr('stroke', '#f6b73c')
      .attr('stroke-width', 1.6);

    const last = slice[slice.length - 1];
    svg.append('circle')
      .attr('cx', x(slice.length - 1))
      .attr('cy', y(last.close))
      .attr('r', 2.5)
      .attr('fill', '#f6b73c');
  };

  const showTooltip = (event, d) => {
    if (d.isETF) {
      tooltip.style('opacity', 0);
      return;
    }

    tooltip
      .style('opacity', 1)
      .html(
        `<div class="tt-title">${d.ticker}</div>` +
        `<div class="tt-sub">${d.fullName}</div>` +
        `<div>Sector: ${d.sector}</div>` +
        `<div class="sparkline"></div>`
      );

    positionTooltip(event);

    const sparklineContainer = tooltip.select('.sparkline');
    sparklineContainer.text('Loading price history...');

    loadPriceHistory(d.ticker)
      .then((series) => renderSparkline(sparklineContainer, series))
      .catch(() => {
        sparklineContainer.text('Price history unavailable');
      });
  };

  const positionTooltip = (event) => {
    const padding = 14;
    const { pageX, pageY } = event;
    tooltip
      .style('left', `${pageX + padding}px`)
      .style('top', `${pageY + padding}px`);
  };

  const hideTooltip = () => {
    tooltip.style('opacity', 0);
  };

  const initTable = (data, onSelect) => {
    const tbody = d3.select('#stock-table tbody');
    const rows = tbody.selectAll('tr')
      .data(data)
      .enter()
      .append('tr')
      .attr('data-ticker', (d) => d.ticker)
      .on('click', (event, d) => {
        onSelect(d.ticker, true);
      });

    rows.append('td').text((d) => d.ticker);
    rows.append('td').text((d) => d.fullName);
    rows.append('td').text((d) => d.sector);
    rows.append('td')
      .attr('class', 'market-cap')
      .text((d) => formatMarketCap(d.marketCap));

    return rows;
  };

  const init = () => {
    const chartWrap = document.getElementById('bubble-chart');
    const width = chartWrap.clientWidth || 700;
    const height = chartWrap.clientHeight || 620;

    const svg = d3.select('#bubble-chart')
      .append('svg')
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('preserveAspectRatio', 'xMidYMid meet');

    d3.csv('data/stock-descriptions.csv').then((rows) => {
      const data = rows.map((row) => {
        const marketCap = row.marketCap && row.marketCap !== '0' ? Number(row.marketCap) : null;
        const sector = row.sector && row.sector.trim() ? row.sector.trim() : 'Other';
        return {
          ticker: row.ticker,
          sector,
          fullName: row['full name'] || row['full name'] || row['full name '] || row['full name'] || row['full name'],
          marketCap,
          isETF: !marketCap,
        };
      });

      const sectors = Array.from(new Set(data.map((d) => d.sector)));
      const colors = sectors.map((s, i) => palette[i % palette.length]);
      const color = d3.scaleOrdinal(sectors, colors);

      const caps = data.filter((d) => d.marketCap).map((d) => d.marketCap);
      const capScale = d3.scaleSqrt()
        .domain(d3.extent(caps))
        .range([12, 55]);

      data.forEach((d) => {
        d.radius = d.marketCap ? capScale(d.marketCap) : 14;
      });

      const center = { x: width / 2, y: height / 2 };
      const clusterRadius = Math.min(width, height) * 0.25;
      const sectorCenters = new Map();
      sectors.forEach((sector, i) => {
        const angle = (Math.PI * 2 * i) / sectors.length;
        sectorCenters.set(sector, {
          x: center.x + clusterRadius * Math.cos(angle),
          y: center.y + clusterRadius * Math.sin(angle),
        });
      });

      const nodes = svg.append('g').attr('class', 'nodes');

      const node = nodes.selectAll('g')
        .data(data)
        .enter()
        .append('g')
        .attr('class', 'node')
        .on('mouseover', showTooltip)
        .on('mousemove', positionTooltip)
        .on('mouseout', hideTooltip)
        .on('click', (event, d) => {
          event.stopPropagation();
          selectTicker(d.ticker, true);
        });

      node.append('circle')
        .attr('r', (d) => d.radius)
        .attr('fill', (d) => color(d.sector));

      node.append('text')
        .text((d) => d.ticker)
        .attr('text-anchor', 'middle')
        .attr('dy', '0.35em')
        .style('font-size', (d) => `${Math.max(8, Math.min(12, d.radius / 2))}px`);

      const legend = svg.append('g')
        .attr('class', 'legend')
        .attr('transform', 'translate(12, 12)');

      const legendItems = legend.selectAll('g')
        .data(sectors)
        .enter()
        .append('g')
        .attr('transform', (d, i) => `translate(0, ${i * 18})`);

      legendItems.append('rect')
        .attr('width', 10)
        .attr('height', 10)
        .attr('rx', 2)
        .attr('fill', (d) => color(d));

      legendItems.append('text')
        .attr('x', 16)
        .attr('y', 9)
        .text((d) => d);

      const tableRows = initTable(data, selectTicker);

      const simulation = d3.forceSimulation(data)
        .force('x', d3.forceX((d) => sectorCenters.get(d.sector).x).strength(0.25))
        .force('y', d3.forceY((d) => sectorCenters.get(d.sector).y).strength(0.25))
        .force('collide', d3.forceCollide((d) => d.radius + 1))
        .force('charge', d3.forceManyBody().strength(-6))
        .force('center', d3.forceCenter(center.x, center.y))
        .on('tick', () => {
          node.attr('transform', (d) => {
            d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
            d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
            return `translate(${d.x}, ${d.y})`;
          });
        });

      const clearSelection = () => {
        state.selected = null;
        node.classed('selected', false);
        tableRows.classed('selected', false);
      };

      function selectTicker(ticker, scrollToRow) {
        state.selected = ticker;
        node.classed('selected', (d) => d.ticker === ticker);
        tableRows.classed('selected', (d) => d.ticker === ticker);
        if (scrollToRow) {
          const row = document.querySelector(`#stock-table tbody tr[data-ticker="${ticker}"]`);
          if (row) {
            row.scrollIntoView({ block: 'center', behavior: 'smooth' });
          }
        }
      }

      svg.on('click', clearSelection);
    });
  };

  init();
})();
EOF"}

